const D = { scale:1, energy:.6, density:.5, speed:1, floatLen:.4, hue:14, x:.5, y:.5, style:'tartan', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const t=K.t, sty=P.style;
const hsh = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };
const BW = Math.max(360, Math.min(700, Math.round(width/2.5)));
const BH = Math.max(120, Math.round(BW*height/width));
if (!S.g || S.bw!==BW || S.bh!==BH){ S.g=createGraphics(BW,BH); S.g.pixelDensity(1); S.bw=BW; S.bh=BH; }
const baseCount = 14 + P.density*62;
const nWarp = Math.max(6, Math.round(baseCount/(0.5 + P.scale*0.9)));
const nWeft = Math.max(6, Math.round(nWarp*BH/BW));
const cellW = BW/nWarp, cellH = BH/nWeft;
const cyc = 3 + Math.round(P.floatLen*5);
const up = Math.max(1, Math.round(cyc*0.5));
const satStep = sty==='brocade' ? 2 : 1;
const off = t*(0.4 + P.speed*0.9);
const en = P.energy;
const lightB = 0.5 + 0.38*Math.sin(t*0.19) + 0.12*Math.sin(t*0.43+1.7);
const waveA = 0.5 + 1.4*en, waveK = 6.28*3/BH;
const bass = Math.min(0.5, A.bass*0.6);

function hsv(h,s,v){ h=((h%360)+360)%360; const c=v*s, x=c*(1-Math.abs((h/60)%2-1)), m=v-c; let r,g,b; const q=(h/60)|0;
  if(q===0){r=c;g=x;b=0;}else if(q===1){r=x;g=c;b=0;}else if(q===2){r=0;g=c;b=x;}else if(q===3){r=0;g=x;b=c;}else if(q===4){r=x;g=0;b=c;}else{r=c;g=0;b=x;}
  return [(r+m)*255,(g+m)*255,(b+m)*255]; }

function warpCol(col){
  if (sty==='denim') return [220,0.55,0.42];
  if (sty==='linen') return [38,0.14,0.66];
  if (sty==='brocade') return [44,0.60,0.62];
  if (sty==='draft') return [P.hue,0.02,0.90];
  const b=col%9; const hu=(P.hue + (b<3?0:b<6?150:38))%360; const sat=b<6?0.62:0.5; const val=(b%2)?0.62:0.5;
  return [hu,sat,val];
}
function weftCol(row){
  if (sty==='denim') return [40,0.08,0.86];
  if (sty==='linen') return [40,0.10,0.58];
  if (sty==='brocade') return [(P.hue+150)%360,0.66,0.5];
  if (sty==='draft') return [P.hue,0.10,0.16];
  const b=row%9; const hu=(P.hue + (b<3?0:b<6?150:38))%360; const sat=b<6?0.6:0.48; const val=(b%2)?0.58:0.46;
  return [hu,sat,val];
}

const g=S.g; g.loadPixels(); const pix=g.pixels;
for (let py=0; py<BH; py++){
  const drape = waveA*Math.sin(py*waveK - t*(0.5+P.speed*0.4));
  const fyr = py/cellH, row=Math.floor(fyr), vin=fyr-row;
