      // grid lines
      if (uin<0.06||vin<0.06){ v*=0.5; }
    }
    v = Math.max(0, Math.min(1, v));
    const rgb = hsv(hsvc[0], s, v);
    const o=(py*BW+px)*4; pix[o]=rgb[0]; pix[o+1]=rgb[1]; pix[o+2]=rgb[2]; pix[o+3]=255;
  }
